# 前綴和 + HashMap（推薦，O(n)）
class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        from collections import defaultdict

        count = defaultdict(int)
        count[0] = 1              # 關鍵：空前綴和出現一次

        prefix_sum = 0
        result = 0
        for num in nums:
            prefix_sum += num
            # 有幾個舊前綴和滿足 prefix_sum - old = k
            result += count[prefix_sum - k]
            count[prefix_sum] += 1
        return result


# 暴力解（O(n²)，小資料可用，面試可先講再優化）
class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        result = 0
        for i in range(n):
            total = 0
            for j in range(i, n):
                total += nums[j]
                if total == k:
                    result += 1
        return result

