// 前綴和 + 開放定址雜湊表：統計有多少個之前的前綴和等於 prefix - k
// 時間複雜度: O(n)（平均），空間複雜度: O(n)
#define HSIZE 65536                       // 2 的冪，大於 2 × 最大元素數

static int keys[HSIZE], vals[HSIZE];
static bool used[HSIZE];

static unsigned slot(int key) {
    unsigned h = (unsigned)key * 2654435761u;   // Knuth 乘法雜湊
    unsigned i = h & (HSIZE - 1);
    while (used[i] && keys[i] != key) i = (i + 1) & (HSIZE - 1);   // 線性探測
    return i;
}

int subarraySum(int* nums, int numsSize, int k) {
    memset(used, 0, sizeof(used));
    unsigned s = slot(0);
    used[s] = true; keys[s] = 0; vals[s] = 1;   // 前綴和 0 出現 1 次

    int prefix = 0, ans = 0;
    for (int i = 0; i < numsSize; i++) {
        prefix += nums[i];
        unsigned q = slot(prefix - k);
        if (used[q]) ans += vals[q];
        unsigned p = slot(prefix);
        if (!used[p]) { used[p] = true; keys[p] = prefix; vals[p] = 0; }
        vals[p]++;
    }
    return ans;
}
